// The MCP tool reference (MH-428): GET /api/mcp/docs, generated by the API from its own tool
// registry (internal/mcp/docs.go), so this page cannot drift from what the server offers.

export type McpDocArg = {
  name: string
  type: string
  required: boolean
  description?: string
  enum?: (string | number)[]
}

export type McpDocTool = {
  name: string
  description: string
  scope: string
  min_role: string
  writes: boolean
  arguments: McpDocArg[]
  input_schema: Record<string, unknown>
  example_call: Record<string, unknown>
  example_result: string
}

export type McpDocGroup = { id: string; title: string; intro: string; tools: McpDocTool[] }

export type McpDocScope = { scope: string; description: string; min_role: string; tools: string[] }

export type McpDocsCatalog = {
  lang: string
  /** The server's canonical URL; "" when the API has no public origin configured. */
  server_url: string
  /** The app's own /api/mcp when server_url is elsewhere (mcp.moharrik.com): still works for older connections. */
  legacy_url?: string
  protocol_versions: string[]
  tool_count: number
  roles: string[]
  scopes: McpDocScope[]
  groups: McpDocGroup[]
}

/** The public path of the docs, for links from the app. */
export function mcpDocsHref(locale: string, anchor?: string) {
  return `/${locale}/docs/mcp${anchor ? `#${anchor}` : ""}`
}

/**
 * The URL an MCP client connects to. A build-time NEXT_PUBLIC_MCP_ORIGIN wins; then the server's
 * own canonical URL (what OAuth tokens are bound to); then this page's origin, which proxies /api
 * to the API. Never a hard-coded localhost: the image is built without NEXT_PUBLIC_MCP_ORIGIN, and
 * that fallback put http://localhost:8120 into every copied command on app.moharrik.com.
 */
export function mcpServerUrl(serverUrl?: string | null): string {
  const env = process.env.NEXT_PUBLIC_MCP_ORIGIN
  if (env) return `${env.replace(/\/$/, "")}/api/mcp`
  if (serverUrl) return serverUrl
  if (typeof window !== "undefined") return `${window.location.origin}/api/mcp`
  return "/api/mcp"
}
